#!/usr/bin/env python3
"""Validate an IELTS Task 2 reviewed HTML report generated by this skill.

Checks the five-part structure, comment anchoring and numbering, Chinese
comments/feedback, self-containment (no external resources), and that the
rendered counts match the JSON review plan.
"""

from __future__ import annotations

import argparse
import base64
import json
import re
from collections import Counter
from html.parser import HTMLParser
from pathlib import Path
from typing import Any

CJK_RE = re.compile(r"[㐀-䶿一-鿿豈-﫿]")
IMAGE_DATA_RE = re.compile(r"^data:image/[A-Za-z0-9.+-]+;base64,[A-Za-z0-9+/=]+$")
MODEL_SECTION_ID = "model-essay"
MODEL_PLAN_KEY = "model_essay"
MODEL_MIN_WORDS = 250
MODEL_MAX_WORDS = 300
VOID_TAGS = {
    "area", "base", "br", "col", "embed", "hr", "img", "input",
    "link", "meta", "param", "source", "track", "wbr",
}
CRITERIA = ["Task Response", "Coherence & Cohesion", "Lexical Resource", "Grammatical Range & Accuracy", "Overall"]


class Node:
    __slots__ = ("tag", "attrs", "children", "parent")

    def __init__(self, tag: str, attrs: dict[str, str], parent: "Node | None" = None) -> None:
        self.tag = tag
        self.attrs = attrs
        self.children: list["Node | str"] = []
        self.parent = parent

    def classes(self) -> set[str]:
        return set((self.attrs.get("class") or "").split())

    def text(self) -> str:
        parts: list[str] = []
        for child in self.children:
            parts.append(child.text() if isinstance(child, Node) else child)
        return "".join(parts)

    def descendants(self):
        for child in self.children:
            if isinstance(child, Node):
                yield child
                yield from child.descendants()

    def ancestors(self):
        node = self.parent
        while node is not None:
            yield node
            node = node.parent


class Builder(HTMLParser):
    def __init__(self) -> None:
        super().__init__(convert_charrefs=True)
        self.root = Node("#document", {})
        self.stack = [self.root]
        self.problems: list[str] = []

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        node = Node(tag, {key: value or "" for key, value in attrs}, self.stack[-1])
        self.stack[-1].children.append(node)
        if tag not in VOID_TAGS:
            self.stack.append(node)

    def handle_startendtag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        node = Node(tag, {key: value or "" for key, value in attrs}, self.stack[-1])
        self.stack[-1].children.append(node)

    def handle_endtag(self, tag: str) -> None:
        if tag in VOID_TAGS:
            return
        if len(self.stack) == 1 or self.stack[-1].tag != tag:
            open_tag = self.stack[-1].tag if len(self.stack) > 1 else "document"
            self.problems.append(f"Unexpected closing tag </{tag}> while <{open_tag}> is open")
            return
        self.stack.pop()

    def handle_data(self, data: str) -> None:
        if data.strip():
            self.stack[-1].children.append(data)


def parse_document(text: str) -> Node:
    builder = Builder()
    builder.feed(text)
    builder.close()
    problems = list(builder.problems)
    if len(builder.stack) != 1:
        unclosed = [node.tag for node in builder.stack[1:]]
        problems.append(f"Unclosed HTML tag(s) at end of document: {unclosed}")
    if problems:
        raise SystemExit("HTML validation failed:\n- " + "\n- ".join(problems))
    if not any(node.tag == "html" for node in builder.root.descendants()):
        raise SystemExit("HTML validation failed:\n- Missing <html> root element")
    return builder.root


def all_nodes(root: Node, tag: str | None = None, cls: str | None = None) -> list[Node]:
    return [
        node
        for node in root.descendants()
        if (tag is None or node.tag == tag) and (cls is None or cls in node.classes())
    ]


def find_id(root: Node, node_id: str) -> Node | None:
    for node in root.descendants():
        if node.attrs.get("id") == node_id:
            return node
    return None


def normalize(text: str) -> str:
    return " ".join(text.split())


def has_cjk(text: str) -> bool:
    return bool(CJK_RE.search(text))


def word_count(text: str) -> int:
    return len(re.findall(r"[A-Za-z]+(?:[-'][A-Za-z]+)?|\d+", text))


def int_comment_id(node: Node, errors: list[str]) -> int | None:
    raw = node.attrs.get("data-comment")
    if raw is None:
        errors.append(f"<{node.tag}> is missing data-comment")
        return None
    try:
        return int(raw)
    except ValueError:
        errors.append(f"<{node.tag}> has non-integer data-comment={raw!r}")
        return None


def load_plan(path: Path) -> dict[str, Any]:
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise SystemExit(f"Could not read review plan {path}: {exc}")


def plan_model_paragraphs(plan: dict[str, Any]) -> list[str]:
    value = plan.get(MODEL_PLAN_KEY, [])
    if isinstance(value, str):
        return [part.strip() for part in value.split("\n") if part.strip()]
    return [str(item).strip() for item in value if str(item).strip()]


def validate(root: Node, plan: dict[str, Any], input_docx: Path | None) -> list[str]:
    errors: list[str] = []

    html_node = next((node for node in root.descendants() if node.tag == "html"), None)
    if html_node is None or html_node.attrs.get("lang") != "zh-CN":
        errors.append('<html> must declare lang="zh-CN"')

    metas = all_nodes(root, "meta")
    if not any(meta.attrs.get("charset", "").lower() == "utf-8" for meta in metas):
        errors.append('Missing <meta charset="utf-8">; the HTML must be UTF-8')

    titles = all_nodes(root, "title")
    if not titles or not has_cjk(titles[0].text()):
        errors.append("Missing or non-Chinese <title>")

    styles = all_nodes(root, "style")
    if not styles:
        errors.append("Missing inline <style> block")
        style_text = ""
    else:
        style_text = "\n".join(style.text() for style in styles)
        if "@media print" not in style_text:
            errors.append("Inline CSS must contain a print stylesheet (@media print)")
        if "mark.comment" not in style_text:
            errors.append("Inline CSS must style mark.comment so anchors stay visible")
        if "print-color-adjust" not in style_text:
            errors.append("Inline CSS must keep the comment highlight in print (print-color-adjust)")
        for forbidden in ("@import", "url("):
            if forbidden in style_text:
                errors.append(f"Inline CSS must not reference external resources ({forbidden!r} found)")

    for node in root.descendants():
        if node.tag in {"script", "link", "iframe", "object", "embed", "base"}:
            errors.append(f"External resource tag <{node.tag}> is not allowed in a self-contained report")
        for attr in ("src", "href", "srcset", "poster"):
            value = node.attrs.get(attr)
            if value is None:
                continue
            if node.tag == "img" and attr == "src":
                if not IMAGE_DATA_RE.match(value):
                    errors.append("Every <img src> must be an inline base64 data URI")
                    continue
                try:
                    base64.b64decode(value.split(",", 1)[1], validate=True)
                except (ValueError, TypeError, IndexError):
                    errors.append("An inline image data URI is not valid base64")
            elif value and not value.startswith("#"):
                errors.append(f"External resource reference found: <{node.tag} {attr}={value[:60]!r}>")

    header = all_nodes(root, "header", "review-header")
    if len(header) != 1:
        errors.append("Missing or duplicated <header class=\"review-header\"> section")
    reviewed = find_id(root, "reviewed-text")
    if reviewed is None:
        errors.append("Missing section#reviewed-text")
    feedback = find_id(root, "feedback")
    if feedback is None:
        errors.append("Missing section#feedback")
    model = find_id(root, MODEL_SECTION_ID)
    if model is None:
        errors.append(f"Missing section#{MODEL_SECTION_ID}")

    for heading in all_nodes(root, "h1") + all_nodes(root, "h2") + all_nodes(root, "h3"):
        if not has_cjk(heading.text()):
            errors.append(f"Section heading must be Chinese: {normalize(heading.text())[:60]!r}")

    all_text = root.text()
    for legacy_heading in (
        "IELTS Writing Task 2 Review", "IELTS Writing Task 1 Review",
        "Reviewed Essay", "Reviewed Answer", "Model Essay", "Model Answer",
    ):
        if legacy_heading in all_text:
            errors.append(f"Legacy visible heading should not appear: {legacy_heading}")

    tables = all_nodes(root, "table", "score-table")
    if len(tables) != 1:
        errors.append("Missing or duplicated table.score-table")
    else:
        table_text = tables[0].text()
        if not has_cjk(table_text):
            errors.append("Score table labels must be in Chinese")
        missing = [criterion for criterion in CRITERIA if criterion not in table_text]
        if missing:
            errors.append(f"Score table is missing criteria: {missing}")
        plan_scores = plan.get("scores") if isinstance(plan.get("scores"), dict) else {}
        for criterion in CRITERIA:
            value = str(plan_scores.get(criterion, "")).strip()
            if value and value not in table_text:
                errors.append(f"Score table value for {criterion} does not match plan: {value}")

    score_notes = all_nodes(root, "ul", "score-notes")
    if len(score_notes) != 1 or not all_nodes(score_notes[0], "li"):
        errors.append("Missing ul.score-notes with Chinese scoring notes")
    else:
        for item in all_nodes(score_notes[0], "li"):
            if not has_cjk(item.text()):
                errors.append("Every score note must contain Chinese: " + normalize(item.text())[:60])

    units = [unit for unit in plan.get("review_units") or [] if str(unit.get("original") or "").strip()]
    plan_comments = [comment for unit in units for comment in (unit.get("comments") or [])]
    plan_targets = Counter(str(comment.get("target") or "").strip() for comment in plan_comments)
    plan_rewrites = sum(1 for unit in units if str(unit.get("rewrite") or "").strip())

    blocks = all_nodes(root, "div", "paragraph-block")
    if len(blocks) != len(units):
        errors.append(f"Paragraph block count {len(blocks)} does not match plan review units {len(units)}")

    marks = all_nodes(root, "mark", "comment")
    items = all_nodes(root, "li", "comment-item")
    if len(marks) != len(plan_comments):
        errors.append(f"Anchor count {len(marks)} does not match plan comment count {len(plan_comments)}")
    rendered_targets = Counter(normalize(mark.attrs.get("data-target", "")) for mark in marks)
    expected_targets = Counter(normalize(target) for target in plan_targets.elements())
    if rendered_targets != expected_targets:
        errors.append("Rendered comment targets do not match the review plan targets")

    mark_ids: list[int] = []
    for mark in marks:
        cid = int_comment_id(mark, errors)
        if cid is not None:
            mark_ids.append(cid)
        target = normalize(mark.attrs.get("data-target", ""))
        if not target:
            errors.append("Every <mark class=\"comment\"> needs a non-empty data-target")
        elif target not in normalize(mark.text()):
            errors.append(f"Comment anchor text does not contain its target {target!r}")
        if not any(node.tag == "p" and "original" in node.classes() for node in mark.ancestors()):
            errors.append("Comment anchors must sit inside <p class=\"original\"> text")

    item_ids: list[int] = []
    item_targets: dict[int, str] = {}
    for item in items:
        cid = int_comment_id(item, errors)
        if cid is not None:
            item_ids.append(cid)
        texts = all_nodes(item, "span", "comment-text")
        targets = all_nodes(item, "span", "comment-target")
        if len(texts) != 1:
            errors.append("Each comment item needs exactly one span.comment-text")
        elif not has_cjk(texts[0].text()):
            errors.append("Every comment must be written in Chinese: " + normalize(texts[0].text())[:60])
        if len(targets) != 1:
            errors.append("Each comment item needs exactly one span.comment-target")
        elif cid is not None:
            item_targets[cid] = normalize(targets[0].text())

    for label, ids in (("anchor", mark_ids), ("comment item", item_ids)):
        duplicates = [cid for cid, count in Counter(ids).items() if count > 1]
        if duplicates:
            errors.append(f"Duplicate {label} numbers: {sorted(duplicates)}")
    if mark_ids and sorted(set(mark_ids)) != list(range(1, max(mark_ids) + 1)):
        errors.append(f"Comment numbering is not continuous from 1: {sorted(set(mark_ids))}")
    if set(mark_ids) != set(item_ids):
        errors.append(f"Anchor numbers {sorted(set(mark_ids))} do not match comment numbers {sorted(set(item_ids))}")
    mark_target_by_id = {}
    for mark in marks:
        cid = int_comment_id(mark, [])
        if cid is not None:
            mark_target_by_id[cid] = normalize(mark.attrs.get("data-target", ""))
    for cid, target in item_targets.items():
        if cid in mark_target_by_id and normalize(target) != mark_target_by_id[cid]:
            errors.append(f"Comment {cid} target text does not match its anchor data-target")

    for block in blocks:
        originals = [
            child for child in block.children
            if isinstance(child, Node) and child.tag == "p" and "original" in child.classes()
        ]
        if len(originals) != 1:
            errors.append("Each paragraph block needs exactly one p.original")
            continue
        if has_cjk(originals[0].text()):
            errors.append("Student original text must stay in English")
        block_marks = all_nodes(block, "mark", "comment")
        block_items = all_nodes(block, "li", "comment-item")
        block_mark_ids = {int_comment_id(mark, []) for mark in block_marks}
        block_item_ids = {int_comment_id(item, []) for item in block_items}
        if block_mark_ids != block_item_ids:
            errors.append("Anchors and comment list in one paragraph block are not matched 1:1")
        for mark in block_marks:
            if mark not in all_nodes(originals[0]):
                errors.append("A comment anchor is outside the p.original it belongs to")

    rewrites = all_nodes(root, "div", "rewrite")
    if len(rewrites) != plan_rewrites:
        errors.append(f"Rewrite block count {len(rewrites)} does not match plan {plan_rewrites}")
    for rewrite in rewrites:
        texts = all_nodes(rewrite, "p", "rewrite-text")
        notes = all_nodes(rewrite, "p", "rewrite-note")
        if len(texts) != 1 or not texts[0].text().strip():
            errors.append("Each rewrite block needs one p.rewrite-text")
        elif has_cjk(texts[0].text()):
            errors.append("Italic Band 7.5 rewrites must stay in English")
        elif not all_nodes(texts[0], "em"):
            errors.append("Band 7.5 rewrites must be rendered in <em> italics")
        if len(notes) != 1 or not has_cjk(notes[0].text()):
            errors.append("Each rewrite block needs a Chinese p.rewrite-note")

    if feedback is not None:
        strengths = all_nodes(feedback, "ul", "strengths")
        if len(strengths) != 1 or not all_nodes(strengths[0], "li"):
            errors.append("Feedback section needs ul.strengths with at least one item")
        else:
            for item in all_nodes(strengths[0], "li"):
                if not has_cjk(item.text()):
                    errors.append("Every strength item must be in Chinese")
        improvements = all_nodes(feedback, "ol", "improvements")
        if len(improvements) != 1:
            errors.append("Feedback section needs ol.improvements")
        else:
            items_list = all_nodes(improvements[0], "li")
            if not 3 <= len(items_list) <= 5:
                errors.append(f"Feedback needs 3-5 priority improvements; got {len(items_list)}")
            for item in items_list:
                if not has_cjk(item.text()):
                    errors.append("Every priority improvement must be in Chinese")

    if model is not None:
        paragraphs = all_nodes(model, "p", "model-paragraph")
        if len(paragraphs) != 4:
            errors.append(f"Model essay must have exactly 4 paragraphs; got {len(paragraphs)}")
        else:
            for paragraph in paragraphs:
                if has_cjk(paragraph.text()):
                    errors.append("Band 8.0 model essay must stay in English")
            if not re.match(r"^in conclusion\b", normalize(paragraphs[-1].text()), flags=re.I):
                errors.append("Task 2 model essay paragraph 4 must begin with 'In conclusion'")
            rendered_words = word_count(" ".join(paragraph.text() for paragraph in paragraphs))
            if not MODEL_MIN_WORDS <= rendered_words <= MODEL_MAX_WORDS:
                errors.append(f"Model essay word count must be {MODEL_MIN_WORDS}-{MODEL_MAX_WORDS}; got {rendered_words}")
            plan_paragraphs = plan_model_paragraphs(plan)
            plan_words = word_count(" ".join(plan_paragraphs))
            if len(plan_paragraphs) != 4:
                errors.append(f"Review plan model essay must have 4 paragraphs; got {len(plan_paragraphs)}")
            if rendered_words != plan_words:
                errors.append(f"Rendered model essay words {rendered_words} do not match plan words {plan_words}")
        wordcount_lines = all_nodes(model, "p", "model-wordcount")
        if len(wordcount_lines) != 1 or not has_cjk(wordcount_lines[0].text()):
            errors.append("Model section needs a Chinese word-count line")
        structure = all_nodes(model, "ol", "structure-notes")
        if len(structure) != 1 or len(all_nodes(structure[0], "li")) != 4:
            errors.append("Model section needs ol.structure-notes with 4 Chinese notes")
        else:
            for item in all_nodes(structure[0], "li"):
                if not has_cjk(item.text()):
                    errors.append("Every model structure note must be in Chinese")

    if header and input_docx is not None and input_docx.name not in header[0].text():
        errors.append(f"Header does not mention the input file name {input_docx.name!r}")

    if not has_cjk(root.text()):
        errors.append("Report contains no Chinese text")
    return errors


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("html", type=Path)
    parser.add_argument("--plan", type=Path, required=True, help="Review plan JSON used to generate the HTML.")
    parser.add_argument("--input-docx", type=Path, default=None, help="Original input DOCX; verifies the header file name.")
    args = parser.parse_args()

    try:
        text = args.html.read_text(encoding="utf-8")
    except UnicodeDecodeError as exc:
        raise SystemExit(f"HTML validation failed:\n- File is not valid UTF-8: {exc}")
    except OSError as exc:
        raise SystemExit(f"Could not read HTML file {args.html}: {exc}")

    plan = load_plan(args.plan)
    root = parse_document(text)
    errors = validate(root, plan, args.input_docx)
    if errors:
        raise SystemExit("HTML validation failed:\n- " + "\n- ".join(errors))

    marks = all_nodes(root, "mark", "comment")
    rewrites = all_nodes(root, "div", "rewrite")
    model = find_id(root, MODEL_SECTION_ID)
    paragraphs = all_nodes(model, "p", "model-paragraph") if model is not None else []
    words = word_count(" ".join(paragraph.text() for paragraph in paragraphs))
    print(f"OK: comments={len(marks)}, rewrites={len(rewrites)}, model_words={words}, sections=5")


if __name__ == "__main__":
    main()
